-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.vessels_near(p_world uuid, p_uid uuid, p_kind text DEFAULT NULL::text)
 RETURNS SETOF placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p
  where p.world_id = p_world and p.kind = 'furniture' and holds_liquid(p)
    and placed_litres(p) >= 1
    and (p_kind is null or placed_liquid(p) = p_kind)
    and near_piece(p_world, p_uid, p, 2.6)
  order by placed_litres(p) desc, p.id
$function$
